package mod.cdv.tnpc.tactical;
import fixture.*;import java.util.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;import net.minecraft.world.entity.EquipmentSlot;import com.google.gson.*;
public class Survivor20Checks {
 static int count;static void ok(boolean value,String message){count++;if(!value)throw new AssertionError(message);}static mod.cdv.tnpc.entity.AutoGunOperator make(World w)throws Exception{var n=new mod.cdv.tnpc.entity.AutoGunOperator(w);Social.init(n);n.tag.putInt("soc_kind",1);n.tag.putInt("soc_persona",2);return n;}
 public static void main(String[] args)throws Exception{
  World w=new World();Player p=new Player(w);p.x=2;Set<String> names=new HashSet<>(),looks=new HashSet<>();int women=0;for(int i=0;i<128;i++){var n=new mod.cdv.tnpc.entity.AutoGunOperator(w);n.uuid=UUID.nameUUIDFromBytes(("survivor"+i).getBytes());Social.init(n);String name=Identity20.name(n);names.add(name);looks.add(n.tag.getInt("soc_skin20")+"");int age=Identity20.age(n);ok(age>=18&&age<=72,"adult age range");ok(name.split(" ").length==2,"fictional first and last name");if(n.tag.getString("soc_gender20").equals("female")){women++;ok(n.tag.getInt("soc_skin20")%2==1,"female appearance matches identity");}else ok(n.tag.getInt("soc_skin20")%2==0,"male appearance matches identity");int skin=n.tag.getInt("soc_skin20");Social.init(n);ok(name.equals(Identity20.name(n))&&age==Identity20.age(n)&&skin==n.tag.getInt("soc_skin20"),"identity and appearance persist across initialization");}
  ok(women>30&&women<98&&names.size()>80&&looks.size()>30,"mixed population and broad appearance/name pools");
  World chatWorld=new World();var n=make(chatWorld);Player close=new Player(chatWorld),far=new Player(chatWorld),other=new Player(new World());close.x=2;far.x=13;var event=new net.neoforged.neoforge.registries.RegisterEvent();SpeechSounds20.register(event);ok(event.entries.size()==10,"registered male/female voice events for five reactions");Expression20.react(n,close,"favor_done");ok(Expression20.current(n).equals("happy")&&chatWorld.sounds==0,"kind action happy reaction without repetitive vocalization");Expression20.tick(n,Social.mem(n),0);ok(n.swings>0,"happy reaction performs offhand gesture");Expression20.tick(n,Social.mem(n),3);ok(Math.abs(n.pitch)>1,"happy head nod animation");ok(close.messages==1&&far.messages==0&&other.messages==0,"named nearby chat never reaches distant players or other dimensions");Expression20.react(n,close,"favor_done");ok(close.messages==1&&chatWorld.sounds==0,"chat and voice rate limits");chatWorld.now=200;Expression20.react(n,close,"insult");ok(Expression20.current(n).equals("angry"),"insult anger");n.tag.putInt("soc_kind",2);Expression20.react(n,close,"threaten");ok(Expression20.current(n).equals("afraid"),"passive reacts with fear");n.tag.putInt("soc_kind",0);Expression20.react(n,close,"insult");ok(Expression20.current(n).equals("hostile"),"hostile reaction");n.tag.putInt("soc_kind",1);Conversation.SESSIONS.put(close,new Conversation.Session(n,9999));Social.mem(n).chatterAt=0;int before=close.messages;Expression20.tick(n,Social.mem(n),2000);ok(close.messages==before,"ambient comments suppressed during a conversation");Conversation.SESSIONS.clear();chatWorld.now=3000;Social.mem(n).chatterAt=0;Expression20.tick(n,Social.mem(n),3000);ok(close.messages==before+1,"idle nearby comment");Expression20.tick(n,Social.mem(n),3001);ok(close.messages==before+1,"ambient NPC cooldown");
  World clinicWorld=new World();var patient=make(clinicWorld);Player healer=new Player(clinicWorld);healer.x=1;NpcMedicine.init(patient);patient.tag.putDouble("np15_hp_head",1);patient.tag.putDouble("np15_hp_leftLeg",1);healer.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack("firstaid:bandage",3));NpcClinic20.open(patient,healer);JsonObject snapshot=JsonParser.parseString(TalkNetwork.last.substring(4)).getAsJsonObject();ok(snapshot.getAsJsonArray("rows").asList().stream().filter(x->x.getAsJsonObject().get("injured").getAsBoolean()).count()==2,"NPC view exposes actual injured parts only");ok(NpcClinic20.action(patient,healer,"treat_9")==0&&NpcClinic20.action(patient,healer,"treat_3")==0,"reject invalid and healthy target parts");double head=patient.tag.getDouble("np15_hp_head");ok(NpcClinic20.action(patient,healer,"treat_4")==1,"select injured leg");clinicWorld.now=60;NpcMedicine.treatment(patient,60);ok(patient.tag.getDouble("np15_hp_leftLeg")>1&&patient.tag.getDouble("np15_hp_head")==head&&healer.getMainHandItem().count==2,"treatment heals selected part only and consumes one bandage");
  World downWorld=new World();var down=make(downWorld);Player rescuer=new Player(downWorld);rescuer.x=1;NpcMedicine.init(down);NpcMedicine.TREATMENTS.put(down,new NpcMedicine.PlayerTreatment(rescuer,new ItemStack("firstaid:bandage",1),0,0));ok(Downed20.blockDeath(down,new Entity.Damage("mob"))&&Downed20.down(down)&&down.hp==1&&down.noAi,"lethal damage becomes downed with AI disabled");ok(!NpcMedicine.TREATMENTS.containsKey(down),"going down interrupts an old bandage job so revive remains available");ok(Social.blockPlayerAttack(down,rescuer),"downed NPC cannot fight");ok(Downed20.blockDeath(down,new Entity.Damage("mob")),"same-shot grace prevents instant double kill");downWorld.now=25;ok(!Downed20.blockDeath(down,new Entity.Damage("mob")),"later lethal hit can finish a downed NPC");ok(Downed20.begin(down,rescuer),"CPR allowed without defibrillator");downWorld.now=185;Downed20.tick(down);ok(!Downed20.down(down)&&!down.noAi&&down.hp==6,"CPR restores NPC after eight seconds, not full health");downWorld.now=300;Downed20.blockDeath(down,new Entity.Damage("mob"));rescuer.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack("lrtactical:defibrillator",1));ok(Downed20.begin(down,rescuer),"defibrillator prioritized");downWorld.now=360;Downed20.tick(down);ok(!Downed20.down(down)&&rescuer.getMainHandItem().damage==1,"three second defib rescue consumes one use");downWorld.now=500;Downed20.blockDeath(down,new Entity.Damage("mob"));Downed20.begin(down,rescuer);rescuer.x=5;downWorld.now=520;Downed20.tick(down);ok(Downed20.down(down)&&!Downed20.RESCUES.containsKey(down),"rescue cancels when rescuer leaves range");downWorld.now=2500;Downed20.tick(down);ok(!down.alive,"unrescued downed NPC dies after deadline");var killed=make(downWorld);ok(!Downed20.blockDeath(killed,new Entity.Damage("genericKill")),"kill command bypasses downed loop");
  World deathWorld=new World();var dead=make(deathWorld);for(int i=0;i<47;i++)dead.bag.add(new ItemStack("minecraft:coal",1));dead.setItemSlot(EquipmentSlot.HEAD,new ItemStack("minecraft:iron_helmet",1));dead.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack("tacz:gun",1));dead.setItemSlot(EquipmentSlot.OFFHAND,new ItemStack("flashlight:flashlight",1));NpcDeath20.store(dead);ok(deathWorld.spawned.size()==1,"one actual Corpse entity created");var corpse=(de.maxhenkel.corpse.entities.CorpseEntity)deathWorld.spawned.getFirst();var cargo=corpse.getDeath();long items=java.util.stream.Stream.of(cargo.main,cargo.armor,cargo.off,cargo.additional).flatMap(List::stream).map(x->(ItemStack)x).filter(x->!x.isEmpty()).mapToInt(x->x.count).sum();ok(items==50&&dead.bag.isEmpty()&&dead.getMainHandItem().isEmpty()&&dead.getItemBySlot(EquipmentSlot.HEAD).isEmpty(),"all bag, armor and hands transferred exactly once including overflow");ok(dead.tag.getBoolean("NpcCorpseQueued14")&&corpse.tag.getBoolean("soc_npc_corpse20"),"remains delivery suppressed and corpse marked as NPC");NpcDeath20.store(dead);ok(deathWorld.spawned.size()==1,"duplicate death callback cannot duplicate corpse");var fallback=make(deathWorld);fallback.bag.add(new ItemStack("minecraft:bread",1));deathWorld.rejectSpawn=true;NpcDeath20.store(fallback);ok(fallback.bag.size()==1&&!fallback.tag.getBoolean("NpcCorpseQueued14"),"rejected spawn retains cargo for native fallback");
  System.out.println("NPC_IDENTITY_REACTIONS_MEDICAL_DOWNED_CORPSE_CHECKS="+count);
 }
}
